import React, { useState, useRef, useEffect, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, MapPin, Building, ArrowRight, Sparkles, Compass } from 'lucide-react';
import { getLocalitiesByCity, CITY_NAMES } from '../data/localities';
import TopBannerBar from './TopBannerBar';
import styles from './HeroSearch.module.css';

/* ── Mode tabs ────────────────────────────────────────────────── */
const MODES = [
  { label: 'Buy',  listingType: 'Sell' },
  { label: 'Rent', listingType: 'Rent' },
];

/* ── Popular cities ──────────────────────────────────────────── */
const POPULAR_CITIES = [
  'Chennai', 'Bengaluru', 'Mumbai', 'Hyderabad', 'Pune', 'Delhi', 'Kolkata', 'Ahmedabad',
];

export default function HeroSearch() {
  const navigate = useNavigate();

  const [mode,            setMode]            = useState(0);
  const [selectedCity,    setSelectedCity]    = useState('Chennai'); // Only changes when a city is confirmed/selected
  const [cityInput,       setCityInput]       = useState('Chennai'); // Tracks typing in the input box
  const [locality,        setLocality]        = useState('');
  const [citySuggestOpen, setCitySuggestOpen] = useState(false);
  const [locSuggestOpen,  setLocSuggestOpen]  = useState(false);

  const cityRef = useRef(null);
  const locRef  = useRef(null);

  // Close dropdowns on outside click; if typing was unfinished, restore selectedCity
  useEffect(() => {
    const handler = (e) => {
      if (cityRef.current && !cityRef.current.contains(e.target)) {
        setCitySuggestOpen(false);
        const match = CITY_NAMES.find(c => c.toLowerCase() === cityInput.trim().toLowerCase());
        if (match) {
          setSelectedCity(match);
          setCityInput(match);
        } else {
          setCityInput(selectedCity);
        }
      }
      if (locRef.current && !locRef.current.contains(e.target)) {
        setLocSuggestOpen(false);
      }
    };
    document.addEventListener('mousedown', handler);
    return () => document.removeEventListener('mousedown', handler);
  }, [cityInput, selectedCity]);

  /* Filtered cities based on what user is typing */
  const matchingCities = useMemo(() => {
    if (!cityInput.trim()) return POPULAR_CITIES;
    const lower = cityInput.toLowerCase();
    return CITY_NAMES.filter(c => c.toLowerCase().includes(lower));
  }, [cityInput]);

  /* Localities for currently confirmed city */
  const activeCityLocalities = useMemo(() => {
    return getLocalitiesByCity(selectedCity || 'Chennai');
  }, [selectedCity]);

  /* Filtered localities based on search query */
  const matchingLocalities = useMemo(() => {
    if (!locality.trim()) return activeCityLocalities;
    const lower = locality.toLowerCase();
    return activeCityLocalities.filter(l => l.toLowerCase().includes(lower));
  }, [activeCityLocalities, locality]);

  /* Popular quick localities for current confirmed city */
  const topLocalitiesForCity = useMemo(() => {
    return activeCityLocalities.slice(0, 8);
  }, [activeCityLocalities]);

  /* Confirms selection of a city: updates the top sentence & input */
  const handlePickCity = (c) => {
    setSelectedCity(c);
    setCityInput(c);
    setCitySuggestOpen(false);
    setLocality('');
    // Open locality suggestions for newly picked city
    setTimeout(() => setLocSuggestOpen(true), 100);
  };

  const handlePickLocality = (loc) => {
    setLocality(loc);
    setLocSuggestOpen(false);
  };

  /* Search handler */
  const handleSearch = (e) => {
    e?.preventDefault();
    const params = new URLSearchParams();
    const m = MODES[mode];
    if (m.listingType)  params.set('listingType',  m.listingType);
    if (m.buildingType) params.set('buildingType', m.buildingType);
    if (m.propertyType) params.set('propertyType', m.propertyType);
    if (selectedCity)   params.set('city', selectedCity);
    if (locality)       params.set('q',    locality);
    navigate('/search?' + params.toString());
  };

  return (
    <div className={styles.hero}>
      {/* Decorative architectural sketch in light yellow wash */}
      <div className={styles.bgSketch} />

      <div className={styles.content}>

        {/* Badge */}
        <div className={styles.tagBadge}>
          <Sparkles size={13} className={styles.tagIcon} />
          <span>India's Most Trusted Real Estate Network</span>
        </div>

        {/* Heading — Shows confirmed selectedCity only, NOT partial typing */}
        <h1 className={styles.heading}>
          Discover Exceptional Real Estate In{' '}
          <span className={styles.cityHighlight}>{selectedCity}</span>
        </h1>
        <p className={styles.subHeading}>
          Handpicked verified villas, modern high-rises, residential plots & Grade-A corporate towers.
        </p>

        {/* ⭐️ Top Banner (Long Width): Directly Above Search Bar with Appear & Disappear Style ⭐️ */}
        <TopBannerBar />

        {/* Search Block (Tabs + Form) */}
        <div className={styles.searchBlock}>
          {/* Mode Tabs */}
          <div className={styles.tabRow}>
            {MODES.map((m, i) => (
              <button
                key={m.label}
                type="button"
                className={`${styles.tab} ${mode === i ? styles.tabActive : ''}`}
                onClick={() => setMode(i)}
              >
                {m.label}
              </button>
            ))}
          </div>

          {/* Search Bar */}
          <form className={styles.searchBar} onSubmit={handleSearch}>

            {/* City input with autocomplete */}
            <div className={styles.cityField} ref={cityRef}>
              <MapPin size={17} className={styles.cityIcon} />
              <input
                type="text"
                className={styles.cityInput}
                placeholder="Select City..."
                value={cityInput}
                onChange={(e) => { setCityInput(e.target.value); setCitySuggestOpen(true); }}
                onFocus={() => setCitySuggestOpen(true)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    e.preventDefault();
                    if (matchingCities.length > 0) {
                      handlePickCity(matchingCities[0]);
                    } else if (cityInput.trim()) {
                      handlePickCity(cityInput.trim());
                    }
                  }
                }}
                autoComplete="off"
              />

              {/* City Autocomplete Dropdown */}
              {citySuggestOpen && (
                <ul className={styles.dropdown}>
                  <li className={styles.dropSectionHeader}>Major Cities in India</li>
                  {matchingCities.slice(0, 10).map(c => (
                    <li
                      key={c}
                      className={`${styles.dropItem} ${selectedCity.toLowerCase() === c.toLowerCase() ? styles.dropItemActive : ''}`}
                      onMouseDown={() => handlePickCity(c)}
                    >
                      <MapPin size={13} className={styles.dropIcon} />
                      <span className={styles.dropItemText}>{c}</span>
                    </li>
                  ))}
                </ul>
              )}
            </div>

            {/* Divider */}
            <div className={styles.divider} />

            {/* Locality Input based on City */}
            <div className={styles.localityField} ref={locRef}>
              <Building size={16} className={styles.localityIcon} />
              <input
                type="text"
                className={styles.localityInput}
                placeholder={`Search locality in ${selectedCity} (e.g. ${topLocalitiesForCity[0] || 'Adyar'}, ${topLocalitiesForCity[1] || 'Anna Nagar'})...`}
                value={locality}
                onChange={(e) => { setLocality(e.target.value); setLocSuggestOpen(true); }}
                onFocus={() => setLocSuggestOpen(true)}
                autoComplete="off"
              />

              {/* Locality Autocomplete Dropdown based on city */}
              {locSuggestOpen && (
                <div className={styles.locDropdown}>
                  <div className={styles.locDropHeader}>
                    <Compass size={13} color="var(--primary)" />
                    <span>Popular Localities in <strong>{selectedCity}</strong> ({activeCityLocalities.length})</span>
                  </div>

                  {/* Quick pills inside dropdown */}
                  <div className={styles.locQuickPills}>
                    {topLocalitiesForCity.slice(0, 6).map(loc => (
                      <button
                        key={loc}
                        type="button"
                        className={styles.locQuickChip}
                        onMouseDown={() => handlePickLocality(loc)}
                      >
                        + {loc}
                      </button>
                    ))}
                  </div>

                  {/* List of matching localities */}
                  <ul className={styles.locList}>
                    {matchingLocalities.length > 0 ? (
                      matchingLocalities.slice(0, 20).map(loc => (
                        <li
                          key={loc}
                          className={styles.dropItem}
                          onMouseDown={() => handlePickLocality(loc)}
                        >
                          <MapPin size={13} className={styles.dropIcon} />
                          <span className={styles.dropItemText}>{loc}</span>
                          <span className={styles.dropCityTag}>{selectedCity}</span>
                        </li>
                      ))
                    ) : (
                      <li className={styles.dropEmpty}>
                        No exact locality match for "{locality}" in {selectedCity}. Press Search to explore all listings.
                      </li>
                    )}
                  </ul>
                </div>
              )}
            </div>

            {/* Search Button (Forest Green) */}
            <button type="submit" className={styles.searchBtn} aria-label="Search Properties">
              <Search size={17} />
              <span>Search</span>
              <ArrowRight size={14} className={styles.searchArrow} />
            </button>
          </form>
        </div>

        {/* Quick Localities based on selected City */}
        {topLocalitiesForCity.length > 0 && (
          <div className={styles.popularRow}>
            <span className={styles.popularLabel}>Localities in {selectedCity}:</span>
            {topLocalitiesForCity.map(loc => (
              <button
                key={loc}
                type="button"
                className={`${styles.popularChip} ${locality === loc ? styles.popularChipActive : ''}`}
                onClick={() => {
                  setLocality(loc);
                  const params = new URLSearchParams();
                  const m = MODES[mode];
                  if (m.listingType)  params.set('listingType',  m.listingType);
                  if (m.buildingType) params.set('buildingType', m.buildingType);
                  if (m.propertyType) params.set('propertyType', m.propertyType);
                  if (selectedCity)   params.set('city', selectedCity);
                  params.set('q', loc);
                  navigate('/search?' + params.toString());
                }}
              >
                {loc}
              </button>
            ))}
          </div>
        )}

        {/* Popular Cities Pills */}
        <div className={styles.popularRow} style={{ marginTop: 2 }}>
          <span className={styles.popularLabel}>Popular Cities:</span>
          {POPULAR_CITIES.map(c => (
            <button
              key={c}
              type="button"
              className={`${styles.popularChip} ${selectedCity.toLowerCase() === c.toLowerCase() ? styles.popularChipActive : ''}`}
              onClick={() => handlePickCity(c)}
            >
              {c}
            </button>
          ))}
        </div>

      </div>
    </div>
  );
}
